/* CS Quest: every word of this game in one language. */
(window.CsqPacks = window.CsqPacks || {})["data-detective"] = Object.assign(window.CsqPacks["data-detective"] || {}, { "he": {"strings":{"Pro":"מקצוען","Explorer":"חוקר","Player {n}":"שחקן {n}","Player {n}, your turn":"שחקן {n}, תורך","Swap! Pass the device.":"החלפה! תעבירו את המכשיר.","Solve mysteries with tables, charts and claims!":"פותרים תעלומות עם טבלאות, דיאגרמות וטענות!","Title screen":"מסך פתיחה","Band: {band}":"רמה: {band}","Two on one device":"שניים על מכשיר אחד","Pair mode on: swap every three cases.":"מצב זוגי פועל: מתחלפים כל שלושה תיקים.","Pair mode off.":"מצב זוגי כבוי.","Pro cases: chapters 4 to 7. Chapter 1 is a warm-up.":"תיקים למקצוענים: פרקים 4 עד 7. פרק 1 הוא חימום.","Explorer cases: chapters 1 to 3 and My Data.":"תיקים לחוקרים: פרקים 1 עד 3 ו״הנתונים שלי״.","Daily Crew Challenge":"האתגר היומי של הצוות","One new case every day":"תיק חדש בכל יום","{n} of {total} stars":"{n} מתוך {total} כוכבים","Coming soon":"בקרוב","{n} cases":"תיקים: {n}","Chapter crown: every star":"כתר הפרק: כל הכוכבים","Chapter map":"מפת הפרקים","Hint":"רמז","Learn card":"כרטיס לימוד","Pause":"השהיה","Class quest: {chapter} · {band}":"משימת כיתה: {chapter} · {band}","Is this claim supported by the chart?":"האם הדיאגרמה תומכת בטענה הזאת?","The claim: “{claim}”":"הטענה: ״{claim}״","Investigate":"לחקור","Got it":"הבנתי","Daily":"יומי","{n} charts made, question {i} of {total}":"נוצרו {n} דיאגרמות, שאלה {i} מתוך {total}","Case {n} of {total}, {stars} stars":"תיק {n} מתוך {total}, {stars} כוכבים","{done} of {n} runs finished ({rate}%).":"הסתיימו {done} מתוך {n} הרצות ({rate}%).","Gap":"פער","Model":"מודל","Real":"במציאות","Off by":"סטייה","Pick a question to start.":"בחר שאלה כדי להתחיל.","Ours %":"שלנו %","Ours":"שלנו","Count":"מספר","Other %":"אחרים %","Other class":"כיתה אחרת","Class pool: {n} charts, {total} answers":"מאגר הכיתה: {n} דיאגרמות, {total} תשובות","Sort by {col}":"מיון לפי {col}","Pictograph":"דיאגרמת תמונות","Counts by {col}":"ספירה לפי {col}","Bar chart":"דיאגרמת עמודות","{n} kids":"{n} ילדים","Table":"טבלה","Bars":"עמודות","Pictures":"תמונות","Another class":"כיתה אחרת","Show percent":"הצג אחוזים","Class pool":"מאגר הכיתה","Group by {col}":"קיבוץ לפי {col}","Run {n} tests":"הרץ {n} בדיקות","Run {n} trials":"הרץ {n} ניסויים","Rule":"כלל","The rule moved. Run the trials again to test it.":"הכלל השתנה. הרץ שוב את הניסויים כדי לבדוק אותו.","Predict first: set the rule, then run the trials.":"קודם תחזית: קבע את הכלל, ואז הרץ את הניסויים.","That is about 8 in 10: balanced!":"זה בערך 8 מתוך 10: מאוזן!","Target: about 8 in 10 finish. Refine the jump.":"המטרה: בערך 8 מתוך 10 מסיימים. כוונן את הקפיצה.","Average miss: {n}%.":"סטייה ממוצעת: {n}%.","The model fits!":"המודל מתאים!","Not yet: refine the rule and run again.":"עוד לא: שפר את הכלל והרץ שוב.","Runs so far: {n}.":"הרצות עד עכשיו: {n}.","Question":"שאלה","{cat}: one less":"{cat}: אחד פחות","{cat}: one more":"{cat}: אחד יותר","Answers: {n}":"תשובות: {n}","Five answers is the least that counts as a case.":"צריך לפחות חמש תשובות כדי שזה ייחשב תיק.","Add to class pool":"הוסף למאגר הכיתה","{n} charts pooled":"{n} דיאגרמות במאגר","Table: {n}":"טבלה: {n}","My prediction for {label}":"התחזית שלי ל{label}","Row: {name}. What should happen to it?":"שורה: {name}. מה לעשות איתה?","Fix, merge, remove, or keep it as it is.":"לתקן, למזג, למחוק או להשאיר כמו שהיא.","Fix to {value}":"תקן ל{value}","Merge (a repeat)":"מזג (כפילות)","Remove (impossible)":"מחק (בלתי אפשרי)","Keep it":"השאר","Added. {n} charts pooled.":"נוסף. {n} דיאגרמות במאגר.","Show me! Tap the bar or row that proves it.":"הראה לי! הקש על העמודה או השורה שמוכיחה את זה.","Show me! Tap the evidence that proves it.":"הראה לי! הקש על הראיה שמוכיחה את זה.","{n} more to tap":"עוד {n} להקיש","Pin this prediction":"נעץ את התחזית","Pick {n}":"בחר {n}","Pin a claim":"נעץ טענה","The view supports a claim. Pin one!":"התצוגה תומכת בטענה. נעץ אחת!","Make a chart with at least {n} answers, then pin a claim.":"צור דיאגרמה עם לפחות {n} תשובות, ואז נעץ טענה.","Show me: the claim card opens when the model fits the trials.":"הראה לי: כרטיס הטענה נפתח כשהמודל מתאים לניסויים.","Show me: the claim card opens when the view on screen answers the question.":"הראה לי: כרטיס הטענה נפתח כשהתצוגה על המסך עונה על השאלה.","Show me first: chart at least {n} answers, then pin your claim.":"קודם הראה לי: דיאגרמה עם לפחות {n} תשובות, ואז נעץ את הטענה.","Show me first: refine the rule until the model fits the trials, then pin it.":"קודם הראה לי: שפר את הכלל עד שהמודל מתאים לניסויים, ואז נעץ אותו.","Show me first: get the view that answers the question on screen, then pin your claim.":"קודם הראה לי: הצג על המסך את מה שעונה על השאלה, ואז נעץ את הטענה.","Pin these {n}":"נעץ את {n} אלה","Look again":"תסתכל שוב","Skip this case":"דלג על התיק","Not that one. Which row or bar shows it?":"לא זה. איזו שורה או עמודה מראה את זה?","Yes! Keep going: tap the rest of the evidence.":"כן! תמשיך: הקש על שאר הראיות.","Good claim! Now show me: tap the bar or row that proves it.":"טענה טובה! עכשיו הראה לי: הקש על העמודה או השורה שמוכיחה אותה.","Good claim! Now show me: tap the evidence that proves it.":"טענה טובה! עכשיו הראה לי: הקש על הראיה שמוכיחה אותה.","Skipped. No stars this time, but the next case is open.":"דילגת. אין כוכבים הפעם, אבל התיק הבא פתוח.","{done} of {n} finished: about 8 in 10. Balanced! Pin the result.":"הסתיימו {done} מתוך {n}: בערך 8 מתוך 10. מאוזן! נעץ את התוצאה.","{done} of {n} finished. Too easy: lower the jump and test again.":"הסתיימו {done} מתוך {n}. קל מדי: הורד את הקפיצה ובדוק שוב.","{done} of {n} finished. Too hard: raise the jump and test again.":"הסתיימו {done} מתוך {n}. קשה מדי: העלה את הקפיצה ובדוק שוב.","The model fits the trials. Pin the rule!":"המודל מתאים לניסויים. נעץ את הכלל!","The model predicts too little. Refine the rule and run again.":"המודל צופה מעט מדי. שפר את הכלל והרץ שוב.","The model predicts too much. Refine the rule and run again.":"המודל צופה יותר מדי. שפר את הכלל והרץ שוב.","That view answers it. Pin your claim!":"התצוגה הזאת עונה על השאלה. נעץ את הטענה!","Chart made! {n} so far.":"נוצרה דיאגרמה! {n} עד עכשיו.","Case closed! {n} of 3 stars.":"התיק נסגר! {n} מתוך 3 כוכבים.","Chart made!":"נוצרה דיאגרמה!","Case closed!":"התיק נסגר!","Case skipped":"דילגת על התיק","Chart {n} made!":"דיאגרמה {n} נוצרה!","Make another chart, or finish and see your total.":"צור עוד דיאגרמה, או סיים וראה את הסיכום.","Another chart":"עוד דיאגרמה","Finish":"סיום","Chapter crown! Dot’s coat has a new color.":"כתר הפרק! למעיל של דוט יש צבע חדש.","{n} of 3 stars today. A new case comes tomorrow.":"{n} מתוך 3 כוכבים היום. תיק חדש יגיע מחר.","Play it again":"שחק שוב","Think about what the data showed you.":"חשוב מה הנתונים הראו לך.","How sure are you?":"כמה אתה בטוח?","Not sure":"לא בטוח","Fairly sure":"די בטוח","Very sure":"בטוח מאוד","Survey done!":"הסקר הסתיים!","All cases closed!":"כל התיקים נסגרו!","{n} charts made.":"נוצרו {n} דיאגרמות.","{chapter}: {n} of {total} stars.":"{chapter}: {n} מתוך {total} כוכבים.","Your work is saved. You can go back to your class page now.":"העבודה שלך נשמרה. אפשר לחזור עכשיו לדף הכיתה.","(This hint costs the third star.)":"(הרמז הזה עולה את הכוכב השלישי.)","Quest Card":"כרטיס משימה","Band":"רמה","Read aloud":"הקראה","Enter a quest code":"הקלד קוד משימה","Settings":"הגדרות","Close":"סגור","Four digits from your teacher: chapter, band, mode, case.":"ארבע ספרות מהמורה: פרק, רמה, מצב, תיק.","Delete":"מחק","That is not a case. Check the four digits with your teacher.":"זה לא תיק. בדוק את ארבע הספרות עם המורה.","Four digits, please.":"ארבע ספרות, בבקשה.","Go":"קדימה","Sort & Group":"למיין ולקבץ","Chart It":"לשרטט","Clues & Claims":"רמזים וטענות","Clean-Up Crew":"צוות הניקיון","Model Makers":"בוני מודלים","Fair Data":"נתונים הוגנים","My Data":"הנתונים שלי","Supported":"נתמכת","Not supported":"לא נתמכת","Can’t tell yet":"אי אפשר לדעת עדיין","Most kids picked {top}.":"הכי הרבה ילדים בחרו: {top}.","Fewest kids picked {low}.":"הכי מעט ילדים בחרו: {low}.","More than half picked {top}.":"יותר ממחצית בחרו: {top}.","Our class has the bigger share of {ours}.":"לכיתה שלנו יש חלק גדול יותר של {ours}.","The other class has the bigger share of {theirs}.":"לכיתה האחרת יש חלק גדול יותר של {theirs}.","Both classes picked {top} most.":"בשתי הכיתות הכי הרבה בחרו: {top}.","Pets at home":"חיות מחמד בבית","Dog":"כלב","Cat":"חתול","Fish":"דג","Bird":"ציפור","Rabbit":"ארנב","None":"אין","Favorite color":"צבע אהוב","Red":"אדום","Blue":"כחול","Green":"ירוק","Yellow":"צהוב","Purple":"סגול","Orange":"כתום","Favorite fruit":"פרי אהוב","Apple":"תפוח","Banana":"בננה","Grape":"ענבים","Pear":"אגס","Melon":"מלון","Berry":"פירות יער","Favorite sport":"ספורט אהוב","Soccer":"כדורגל","Basketball":"כדורסל","Swimming":"שחייה","Tennis":"טניס","Running":"ריצה","Dance":"ריקוד","How we get to school":"איך מגיעים לבית הספר","Walk":"ברגל","Bike":"אופניים","Bus":"אוטובוס","Car":"מכונית","Scooter":"קורקינט","Train":"רכבת","Our own question":"השאלה שלנו","Option A":"אפשרות א׳","Option B":"אפשרות ב׳","Option C":"אפשרות ג׳","Option D":"אפשרות ד׳","Option E":"אפשרות ה׳","Option F":"אפשרות ו׳","Option G":"אפשרות ז׳","Option H":"אפשרות ח׳","The Missing Lunchbox":"קופסת האוכל שנעלמה","A lunchbox went missing from the hall after lunch. Here is who was where, and when.":"קופסת אוכל נעלמה מהמסדרון אחרי ארוחת הצהריים. הנה מי היה איפה, ומתי.","Who was last in the hall?":"מי היה אחרון במסדרון?","Sorted by When, the last Hall row is Gus at 3:10. Jo was later, but in the Yard.":"במיון לפי ״מתי״, שורת המסדרון האחרונה היא גאס ב־3:10. ג׳ו היה אחר כך, אבל בחצר.","Data is facts in rows":"נתונים הם עובדות בשורות","Which column would tell us when each kid was there?":"איזו עמודה תגיד לנו מתי כל ילד היה שם?","The When column is glowing. Tap its header to sort by time.":"העמודה ״מתי״ זוהרת. הקש על הכותרת שלה כדי למיין לפי זמן.","I sorted the table by When for you. Now read the Hall rows from the bottom.":"מיינתי לך את הטבלה לפי ״מתי״. עכשיו קרא את שורות המסדרון מלמטה.","What does sorting a table do?":"מה עושה מיון של טבלה?","Puts the rows in order":"מסדר את השורות","Deletes rows":"מוחק שורות","Adds new facts":"מוסיף עובדות חדשות","Gus":"גאס","Jo":"ג׳ו","Eli":"אלי","Who":"מי","Where":"איפה","When":"מתי","Ari":"ארי","Hall":"מסדרון","Bo":"בו","Yard":"חצר","Cy":"סאי","Dee":"די","Library":"ספרייה","Fay":"פיי","Kai":"קאי","Ida":"אידה","Tower Trouble":"תעלומת המגדלים","Four teams built block towers. The judge lost the ribbon!":"ארבע קבוצות בנו מגדלים מקוביות. השופט איבד את הסרט!","Which team built the tallest tower?":"איזו קבוצה בנתה את המגדל הגבוה ביותר?","Sorted by Blocks, the biggest number is 21, and that row is the Foxes.":"במיון לפי ״קוביות״, המספר הגדול ביותר הוא 21, ובשורה הזאת השועלים.","Which column holds the height of each tower?":"באיזו עמודה הגובה של כל מגדל?","Blocks is glowing. Tap it to sort by height.":"״קוביות״ זוהרת. הקש עליה כדי למיין לפי גובה.","Sorted by Blocks for you. The biggest number is at one end.":"מיינתי לך לפי ״קוביות״. המספר הגדול ביותר נמצא באחד הקצוות.","To find the biggest number fast, you should…":"כדי למצוא מהר את המספר הגדול ביותר, כדאי…","Sort by that column":"למיין לפי העמודה הזאת","Sort by the first column":"למיין לפי העמודה הראשונה","Count every row":"לספור כל שורה","Foxes":"שועלים","Ducks":"ברווזים","Frogs":"צפרדעים","Team":"קבוצה","Blocks":"קוביות","Color":"צבע","Owls":"ינשופים","Bees":"דבורים","Cats":"חתולים","Pet Parade":"מצעד חיות המחמד","Every kid in the class drew their pet. Dot wants one number: which pet wins?":"כל ילד בכיתה צייר את חיית המחמד שלו. דוט רוצה מספר אחד: איזו חיה מנצחת?","Which pet is most common in the class?":"איזו חיית מחמד הכי נפוצה בכיתה?","Grouped by Pet, the Dog bar is the tallest: 4 kids.":"בקיבוץ לפי ״חיה״, העמודה של הכלב הכי גבוהה: 4 ילדים.","Group counts by kind":"קיבוץ סופר לפי סוג","Sorting lists every row. Group puts the rows with the same value together and counts them, so you see how many of each kind.":"מיון מציג כל שורה. קיבוץ מאחד שורות עם אותו ערך וסופר אותן, כך שרואים כמה יש מכל סוג.","Sorting lists every row. What would count the pets instead?":"מיון מציג כל שורה. מה יספור את החיות במקום זה?","The Group button is glowing. Group by Pet to count each kind.":"כפתור הקיבוץ זוהר. קבץ לפי ״חיה״ כדי לספור כל סוג.","I grouped the rows by Pet for you. Read the counts.":"קיבצתי לך את השורות לפי ״חיה״. קרא את המספרים.","Grouping by Pet shows you…":"קיבוץ לפי ״חיה״ מראה לך…","How many of each pet":"כמה יש מכל חיה","Who has the oldest pet":"למי יש את החיה הכי זקנה","The pets in time order":"את החיות לפי סדר זמן","Name":"שם","Pet":"חיה","Library Days":"ימי הספרייה","The library keeps a visitor list. Which day needs an extra helper?":"הספרייה מנהלת רשימת מבקרים. באיזה יום צריך עוד עוזר?","On which day did the most kids visit?":"באיזה יום ביקרו הכי הרבה ילדים?","Grouped by Day, Tuesday has the most visits: 3.":"בקיבוץ לפי ״יום״, ביום שלישי הכי הרבה ביקורים: 3.","Do you need the names, or how many per day?":"אתה צריך את השמות, או כמה בכל יום?","Group is glowing. Group by Day.":"הקיבוץ זוהר. קבץ לפי ״יום״.","Grouped by Day for you. Which bar is tallest?":"קיבצתי לך לפי ״יום״. איזו עמודה הכי גבוהה?","Which view answers “how many per day?” fastest?":"איזו תצוגה עונה הכי מהר על ״כמה בכל יום?״","Group by Day":"קבץ לפי יום","Sort by Name":"מיין לפי שם","The plain list":"הרשימה הרגילה","Tuesday":"שלישי","Monday":"שני","Friday":"שישי","Day":"יום","Lu":"לו","Wednesday":"רביעי","Mo":"מו","Nia":"ניה","Ori":"אורי","Pia":"פיה","Rae":"ריי","Fastest Lap":"ההקפה המהירה","Sports day! Everyone ran one lap. One column is just for fun.":"יום ספורט! כולם רצו הקפה אחת. עמודה אחת היא סתם בשביל הכיף.","Who ran the fastest lap?":"מי רץ את ההקפה הכי מהר?","Sorted by Seconds, the smallest number is 45, and that is Uma. Shoes do not matter here.":"במיון לפי ״שניות״, המספר הקטן ביותר הוא 45, וזו אומה. הנעליים לא משנות כאן.","Fastest means the fewest seconds. Which column has seconds?":"הכי מהר זה הכי מעט שניות. באיזו עמודה השניות?","Seconds is glowing. Tap it.":"״שניות״ זוהרת. הקש עליה.","Sorted by Seconds for you. Fastest is the smallest number.":"מיינתי לך לפי ״שניות״. הכי מהיר זה המספר הקטן ביותר.","Uma":"אומה","Seconds":"שניות","Shoes":"נעליים","Sol":"סול","Tam":"טאם","Vic":"ויק","Snack Vote":"הצבעת חטיפים","The class voted for a party snack. Dot wants to know what to skip.":"הכיתה הצביעה על חטיף למסיבה. דוט רוצה לדעת על מה לוותר.","Which snack did the fewest kids pick?":"איזה חטיף הכי מעט ילדים בחרו?","Grouped by Snack, Crackers has the shortest bar: 1 vote.":"בקיבוץ לפי ״חטיף״, לקרקרים יש העמודה הכי קצרה: קול אחד.","Fewest means the smallest count. How do you get counts?":"הכי מעט זה המספר הקטן ביותר. איך מקבלים מספרים?","Group by Snack.":"קבץ לפי ״חטיף״.","Grouped for you. Look for the shortest bar.":"קיבצתי לך. חפש את העמודה הכי קצרה.","The shortest bar in a group count means…":"העמודה הכי קצרה בספירה מקובצת אומרת…","The fewest of that kind":"שמהסוג הזה יש הכי מעט","The most of that kind":"שמהסוג הזה יש הכי הרבה","A mistake":"שיש טעות","Crackers":"קרקרים","Fruit":"פירות","Popcorn":"פופקורן","Snack":"חטיף","Fruit Bowl":"קערת פירות","The lunch helper counted fruit picks. Pick the view that shows the winner at a glance.":"עוזר הצהריים ספר את בחירות הפירות. בחר תצוגה שמראה את המנצח במבט אחד.","Which fruit was picked most?":"איזה פרי נבחר הכי הרבה?","The bar chart shows Grape with the tallest bar: 7.":"בדיאגרמת העמודות לענבים יש העמודה הכי גבוהה: 7.","Charts show the shape":"דיאגרמות מראות צורה","A bar chart turns counts into bars, so the biggest and smallest jump out. A pictograph uses pictures. A table keeps every exact fact.":"דיאגרמת עמודות הופכת מספרים לעמודות, כך שהגדול והקטן קופצים לעין. דיאגרמת תמונות משתמשת בתמונות. טבלה שומרת כל עובדה מדויקת.","Which view shows big and small at a glance?":"איזו תצוגה מראה גדול וקטן במבט אחד?","The Bars button is glowing.":"כפתור העמודות זוהר.","Switched to bars for you. The tallest bar wins.":"עברתי לעמודות בשבילך. העמודה הכי גבוהה מנצחת.","A bar chart is best for…":"דיאגרמת עמודות הכי טובה ל…","Comparing amounts at a glance":"השוואת כמויות במבט אחד","Hiding the numbers":"הסתרת המספרים","Listing every name":"רשימת כל השמות","Kids":"ילדים","Build the Bars":"בונים עמודות","Dot has the pet counts in a table but the chart is empty. Build it!":"לדוט יש את מספרי חיות המחמד בטבלה, אבל הדיאגרמה ריקה. בנה אותה!","Make the bars match the table. Then: which pet is most common?":"התאם את העמודות לטבלה. ואז: איזו חיה הכי נפוצה?","When the bars match the table, Dog is the tallest: 5.":"כשהעמודות מתאימות לטבלה, הכלב הכי גבוה: 5.","Each bar should be as tall as its number in the table.":"כל עמודה צריכה להיות גבוהה כמו המספר שלה בטבלה.","The Dog stepper is glowing: tap + until Dog shows 5.":"הכפתורים של ״כלב״ זוהרים: הקש + עד שכלב מראה 5.","I set Dog to 5 for you. Match the other three.":"קבעתי לך כלב על 5. התאם את שלושת האחרים.","A bar’s height should equal…":"הגובה של עמודה צריך להיות שווה ל…","Its number in the table":"המספר שלה בטבלה","The biggest number":"המספר הגדול ביותר","Any height you like":"כל גובה שתרצה","Picture This":"תמונה שווה אלף מילים","The sports club made a pictograph. Each picture stands for 2 kids.":"מועדון הספורט הכין דיאגרמת תמונות. כל תמונה מייצגת 2 ילדים.","How many more kids chose Soccer than Swimming?":"בכמה ילדים יותר בחרו בכדורגל מאשר בשחייה?","Soccer has 8 and Swimming has 4. 8 minus 4 is 4.":"לכדורגל 8 ולשחייה 4. 8 פחות 4 זה 4.","Which view shows the two amounts side by side? Each picture is 2 kids.":"איזו תצוגה מראה את שתי הכמויות זו ליד זו? כל תמונה היא 2 ילדים.","The Pictures button is glowing.":"כפתור התמונות זוהר.","Switched to pictures for you. Soccer 8, Swimming 4: take the smaller from the bigger.":"עברתי לתמונות בשבילך. כדורגל 8, שחייה 4: חסר את הקטן מהגדול.","In this pictograph one picture means…":"בדיאגרמת התמונות הזאת תמונה אחת אומרת…","2 kids":"2 ילדים","1 kid":"ילד אחד","10 kids":"10 ילדים","Sport":"ספורט","Who Picked Grape?":"מי בחר ענבים?","A chart is great for amounts, but someone has a question only a table can answer.":"דיאגרמה מצוינת לכמויות, אבל למישהו יש שאלה שרק טבלה יכולה לענות עליה.","Which kid picked Grape?":"איזה ילד בחר ענבים?","Only the table keeps the names. Nia’s row says Grape.":"רק הטבלה שומרת את השמות. בשורה של ניה כתוב ענבים.","Does a bar chart show names?":"האם דיאגרמת עמודות מראה שמות?","The Table button is glowing.":"כפתור הטבלה זוהר.","Switched to the table for you. Find the Grape row.":"עברתי לטבלה בשבילך. מצא את שורת הענבים.","A chart loses…":"דיאגרמה מאבדת…","The single facts, like names":"את העובדות הבודדות, כמו שמות","The totals":"את הסכומים","Nothing at all":"שום דבר","The Empty Bar":"העמודה הריקה","Color vote! Build the bars and spot the color nobody chose.":"הצבעת צבעים! בנה את העמודות ומצא את הצבע שאף אחד לא בחר.","Which color did nobody pick?":"איזה צבע אף אחד לא בחר?","With the bars built, Green stays at 0: nobody picked it.":"כשהעמודות בנויות, ירוק נשאר על 0: אף אחד לא בחר בו.","Build each bar to its number. One of them stays flat.":"בנה כל עמודה עד המספר שלה. אחת מהן נשארת שטוחה.","Green is glowing. Its number is 0.":"ירוק זוהר. המספר שלו הוא 0.","I built Red to 3 for you. Finish the rest, then find the flat bar.":"בניתי לך את אדום עד 3. סיים את השאר, ואז מצא את העמודה השטוחה.","A bar at 0 means…":"עמודה על 0 אומרת…","Nobody picked it":"שאף אחד לא בחר בזה","It was picked most":"שזה נבחר הכי הרבה","The data is wrong":"שהנתונים שגויים","Votes":"קולות","The Plant Race":"מרוץ הצמחים","Dot measured a bean plant every day for five days.":"דוט מדדה צמח שעועית כל יום במשך חמישה ימים.","The plant grows about 2 cm a day.":"הצמח גדל בערך 2 ס״מ ביום.","Each bar is 2 cm taller than the one before: 2, 4, 6, 8, 10. That supports the claim.":"כל עמודה גבוהה ב־2 ס״מ מזו שלפניה: 2, 4, 6, 8, 10. זה תומך בטענה.","Claims need evidence":"טענות צריכות ראיות","A claim is something you say is true. The chart is the evidence. It can support the claim, go against it, or be too small to tell yet.":"טענה היא משהו שאתה אומר שהוא נכון. הדיאגרמה היא הראיה. היא יכולה לתמוך בטענה, לסתור אותה, או להיות קטנה מדי כדי לדעת עדיין.","How much does each bar grow from one day to the next?":"בכמה גדלה כל עמודה מיום ליום?","Day 2 and Day 3 are glowing. Compare their heights.":"יום 2 ויום 3 זוהרים. השווה את הגבהים שלהם.","4 to 6 is 2 more. Every day adds 2. The claim is supported.":"מ־4 ל־6 זה 2 יותר. כל יום מוסיף 2. הטענה נתמכת.","A claim is supported when…":"טענה נתמכת כש…","The data shows it":"הנתונים מראים אותה","It sounds right":"היא נשמעת נכונה","A friend agrees":"חבר מסכים","Day 1":"יום 1","Day 2":"יום 2","Day 3":"יום 3","Day 4":"יום 4","Day 5":"יום 5","cm":"ס״מ","Bike Rack":"מתקן האופניים","The caretaker counted bikes at the rack every morning this week.":"השרת ספר את האופניים במתקן כל בוקר השבוע.","Friday is the busiest bike day.":"יום שישי הוא היום עם הכי הרבה אופניים.","Thursday’s bar is the tallest: 15. Friday has 13. The chart goes against the claim.":"העמודה של חמישי הכי גבוהה: 15. לשישי 13. הדיאגרמה סותרת את הטענה.","Which bar is the tallest?":"איזו עמודה הכי גבוהה?","Thursday is glowing. Compare it with Friday.":"חמישי זוהר. השווה אותו לשישי.","Thursday 15 is more than Friday 13, so the claim is not supported.":"חמישי 15 זה יותר משישי 13, אז הטענה לא נתמכת.","The chart says Thursday 15 and Friday 13. “Friday is busiest” is…":"הדיאגרמה אומרת חמישי 15 ושישי 13. ״בשישי הכי הרבה״ היא…","Impossible to check":"אי אפשר לבדוק","Thursday":"חמישי","Bikes":"אופניים","Two Points Is a Hunch":"שתי נקודות הן רק ניחוש","A sunflower was measured on two days. Someone is already making a big prediction.":"חמנייה נמדדה ביומיים. מישהו כבר עושה תחזית גדולה.","It will be 20 cm tall by day 10.":"ביום 10 היא תהיה בגובה 20 ס״מ.","Two bars is a hunch, not a case. We need more days before we can tell.":"שתי עמודות הן ניחוש, לא תיק. צריך עוד ימים כדי לדעת.","How many days of data do we have?":"כמה ימים של נתונים יש לנו?","Both bars are glowing. Is that enough to see a pattern?":"שתי העמודות זוהרות. זה מספיק כדי לראות דפוס?","Two points can make any line. Pick Can’t tell yet.":"דרך שתי נקודות אפשר להעביר כל קו. בחר ״אי אפשר לדעת עדיין״.","Predict Day 6":"תחזית ליום 6","Back to the bean plant. Five days are in. What will day 6 measure?":"חזרה לצמח השעועית. יש חמישה ימים. כמה הוא יימדד ביום 6?","Slide to your prediction for day 6, then pin it.":"גרור לתחזית שלך ליום 6, ואז נעץ אותה.","The plant adds 2 cm a day: 10 on day 5, so day 6 should be about 12.":"הצמח מוסיף 2 ס״מ ביום: 10 ביום 5, אז ביום 6 בערך 12.","What is the step from one day to the next?":"מה הצעד מיום ליום?","Day 4 and Day 5 are glowing: 8 then 10.":"יום 4 ויום 5 זוהרים: 8 ואחר כך 10.","10 plus 2 is 12. Slide to 12.":"10 ועוד 2 זה 12. גרור ל־12.","A prediction from a steady pattern is…":"תחזית מדפוס קבוע היא…","A good guess with evidence":"ניחוש טוב עם ראיות","Always exactly right":"תמיד מדויקת לגמרי","Just luck":"סתם מזל","Day 6":"יום 6","Shoes and Books":"נעליים וספרים","A class list has shoe sizes and books read this month. Someone sees a link.":"ברשימה של הכיתה יש מידות נעליים וספרים שנקראו החודש. מישהו רואה קשר.","Kids with bigger shoes read more books.":"ילדים עם נעליים גדולות יותר קוראים יותר ספרים.","Two columns in one table…":"שתי עמודות באותה טבלה…","Do not have to be connected":"לא חייבות להיות קשורות","Are always connected":"תמיד קשורות","Must be sorted together":"חייבות להיות ממוינות יחד","Shoe size":"מידת נעליים","Books":"ספרים","Hair and Laps":"שיער והקפות","Sports day again. The list has hair color and laps run. A new claim is on the board.":"שוב יום ספורט. ברשימה יש צבע שיער ומספר הקפות. על הלוח יש טענה חדשה.","Everyone ran at least 3 laps.":"כולם רצו לפחות 3 הקפות.","The smallest number in Laps is 3, so everyone ran at least 3. Hair color does not come into it.":"המספר הקטן ביותר ב״הקפות״ הוא 3, אז כולם רצו לפחות 3. צבע השיער לא קשור לזה.","What is the smallest number in the Laps column?":"מה המספר הקטן ביותר בעמודה ״הקפות״?","Ida and Kai are glowing: the smallest laps.":"אידה וקאי זוהרים: הכי מעט הקפות.","The smallest is 3, which is at least 3. Supported.":"הקטן ביותר הוא 3, וזה לפחות 3. נתמכת.","Hair":"שיער","Laps":"הקפות","Brown":"חום","Black":"שחור","Blond":"בלונדיני","Twelve Pets":"שתים־עשרה חיות","Twelve kids typed their pet. Some typed in a hurry. Clean the list before counting.":"שנים־עשר ילדים הקלידו את חיית המחמד שלהם. חלק מיהרו. נקה את הרשימה לפני שסופרים.","How many kids have a dog?":"לכמה ילדים יש כלב?","After fixing the three misspelled dogs, the Dog group counts 7.":"אחרי תיקון שלושת הכלבים עם שגיאות כתיב, בקבוצת הכלב יש 7.","Messy data lies":"נתונים מבולגנים משקרים","Real data has typos, double entries and impossible numbers. Clean it first: fix a typo, merge a duplicate, remove what cannot be true. Then count.":"בנתונים אמיתיים יש שגיאות הקלדה, כפילויות ומספרים בלתי אפשריים. קודם נקה: תקן שגיאה, מזג כפילות, מחק מה שלא יכול להיות נכון. ואז ספור.","Some rows say the same pet in a different way. Can you spot them?":"בחלק מהשורות אותה חיה כתובה בצורה אחרת. אתה מוצא אותן?","The odd rows are glowing. Tap one and fix its spelling.":"השורות המוזרות זוהרות. הקש על אחת ותקן את הכתיב.","I fixed Cy’s row to Dog. Fix the other two, then group by Pet.":"תיקנתי לך את השורה של סאי לכלב. תקן את השתיים האחרות, ואז קבץ לפי ״חיה״.","“dog”, “Dog” and “d0g” should be…":"״כלב״, ״כאלב״ ו״כלכ״ צריכים…","Fixed to one spelling":"להיות מתוקנים לכתיב אחד","Counted as three pets":"להיספר כשלוש חיות","Removed":"להימחק","dog":"כאלב","d0g":"כלכ","Dgo":"כבל","Double Trouble":"כפול צרות","Which club has the most kids?":"באיזה חוג יש הכי הרבה ילדים?","Once Ori and Sol are counted once each, Art has 3 and Chess has 2.":"כשסופרים את אורי וסול פעם אחת כל אחד, באמנות 3 ובשחמט 2.","Is anyone on the list twice?":"יש מישהו ברשימה פעמיים?","The repeated rows are glowing. Tap one and merge it.":"השורות החוזרות זוהרות. הקש על אחת ומזג אותה.","I merged Ori’s second row. Merge Sol’s, then group by Club.":"מיזגתי את השורה השנייה של אורי. מזג את של סול, ואז קבץ לפי ״חוג״.","A duplicate row should be…":"שורה כפולה צריכה…","Merged into one":"להתמזג לאחת","Counted twice":"להיספר פעמיים","Fixed to a new name":"לקבל שם חדש","Art":"אמנות","Chess":"שחמט","Music":"מוזיקה","Club":"חוג","Impossible!":"בלתי אפשרי!","Kids typed their age for the reading club. Two numbers cannot be true.":"ילדים הקלידו את הגיל שלהם לחוג הקריאה. שני מספרים לא יכולים להיות נכונים.","What is the most common age?":"מה הגיל הכי נפוץ?","99 and 1 cannot be club ages. Without them, age 10 is the biggest group: 4 kids.":"99 ו־1 לא יכולים להיות גילים בחוג. בלעדיהם, גיל 10 הוא הקבוצה הגדולה: 4 ילדים.","Which ages could not be a kid in this club?":"אילו גילים לא יכולים להיות של ילד בחוג הזה?","Two rows are glowing. Tap one and remove it.":"שתי שורות זוהרות. הקש על אחת ומחק אותה.","I removed the 99. Remove the other impossible age, then group by Age.":"מחקתי את ה־99. מחק את הגיל הבלתי אפשרי השני, ואז קבץ לפי ״גיל״.","An age of 99 in a kids’ club list is…":"גיל 99 ברשימה של חוג ילדים הוא…","An impossible value to remove":"ערך בלתי אפשרי שצריך למחוק","The oldest member":"החבר הכי מבוגר","A typo for 9 that you keep":"שגיאת הקלדה של 9 שמשאירים","Age":"גיל","The Big Mess":"הבלגן הגדול","Sports club sign-ups: typos, a double entry and an impossible number, all in one list.":"הרשמה למועדון הספורט: שגיאות כתיב, כפילות ומספר בלתי אפשרי, הכול ברשימה אחת.","Which sport has the most kids?":"באיזה ספורט הכי הרבה ילדים?","Clean, the list has 4 Tennis kids, 3 Soccer and 2 Swimming.":"ברשימה הנקייה יש 4 בטניס, 3 בכדורגל ו־2 בשחייה.","Look for three kinds of mess: spelling, a repeat, an impossible number.":"חפש שלושה סוגי בלגן: כתיב, כפילות, מספר בלתי אפשרי.","The messy rows are glowing. Fix, merge or remove each one.":"השורות המבולגנות זוהרות. תקן, מזג או מחק כל אחת.","I fixed Lu’s row. Do the other three, then group by Sport.":"תיקנתי את השורה של לו. טפל בשלוש האחרות, ואז קבץ לפי ״ספורט״.","Which fix is right for an age of 120?":"איזה תיקון נכון לגיל 120?","Remove the row":"למחוק את השורה","Fix the spelling":"לתקן את הכתיב","Merge it":"למזג אותה","soccer":"כדורגעל","Tenis":"טנס","Fair Shares":"חלקים הוגנים","Two classes counted who walks to school. Class B has more walkers, but it is a bigger class.":"שתי כיתות ספרו מי הולך ברגל לבית הספר. בכיתה ב׳ יש יותר הולכי רגל, אבל היא כיתה גדולה יותר.","Which class has the bigger share of walkers?":"לאיזו כיתה יש חלק גדול יותר של הולכי רגל?","As a share, Class A is 50% and Class B is 40%. More walkers, but a smaller share.":"בחלקים, כיתה א׳ היא 50% וכיתה ב׳ 40%. יותר הולכי רגל, אבל חלק קטן יותר.","Counts to percent":"ממספרים לאחוזים","To compare groups of different sizes, turn counts into percent: part divided by whole, times 100. Then every group is out of 100.":"כדי להשוות קבוצות בגדלים שונים, הפוך מספרים לאחוזים: החלק חלקי השלם, כפול 100. כך כל קבוצה היא מתוך 100.","12 is more than 10, but the classes are different sizes. What would make them fair to compare?":"12 זה יותר מ־10, אבל הכיתות בגדלים שונים. מה יאפשר להשוות ביניהן בהוגנות?","The % button is glowing.":"כפתור ה־% זוהר.","Switched to percent for you: A 50%, B 40%.":"עברתי לאחוזים בשבילך: א׳ 50%, ב׳ 40%.","Why turn counts into percent?":"למה להפוך מספרים לאחוזים?","To compare groups of different sizes":"כדי להשוות קבוצות בגדלים שונים","To make the numbers bigger":"כדי שהמספרים יהיו גדולים יותר","To remove bad rows":"כדי למחוק שורות גרועות","Class A":"כיתה א׳","Class B":"כיתה ב׳","Class":"כיתה","Tidy, Then Compare":"לסדר, ואז להשוות","Three classes sent their recycling counts. One row cannot be right. Fix the list, then compare shares.":"שלוש כיתות שלחו את מספרי המיחזור שלהן. שורה אחת לא יכולה להיות נכונה. תקן את הרשימה, ואז השווה חלקים.","Which class recycled the biggest share of its lunches?":"איזו כיתה מיחזרה את החלק הגדול ביותר מארוחות הצהריים שלה?","Class C says 30 of 20, which cannot be. Without it: A 75%, B 80%.":"כיתה ג׳ אומרת 30 מתוך 20, וזה לא ייתכן. בלעדיה: א׳ 75%, ב׳ 80%.","One class recycled more lunches than it had. Which one?":"כיתה אחת מיחזרה יותר ארוחות ממה שהיו לה. איזו?","Class C is glowing. Remove it, then use %.":"כיתה ג׳ זוהרת. מחק אותה, ואז השתמש ב־%.","I removed Class C. Now tap % to compare shares.":"מחקתי את כיתה ג׳. עכשיו הקש % כדי להשוות חלקים.","30 recycled out of 20 lunches is…":"30 שמוחזרו מתוך 20 ארוחות זה…","Impossible":"בלתי אפשרי","A great result":"תוצאה מעולה","Class C":"כיתה ג׳","Recycled":"מוחזרו","Lunches":"ארוחות","Ramp Rule":"כלל המדרון","A toy car rolls off a ramp. Dot’s model says the distance it rolls is some number times the ramp height.":"מכונית צעצוע מתגלגלת ממדרון. לפי המודל של דוט, המרחק שהיא מתגלגלת הוא מספר כלשהו כפול גובה המדרון.","Find the number that makes the model fit the trials, then pin the rule.":"מצא את המספר שגורם למודל להתאים לניסויים, ואז נעץ את הכלל.","With 2 × height the model lands within a few cm of every trial. 1 × is far too short and 4 × far too long.":"עם 2 × גובה המודל נוחת במרחק כמה ס״מ מכל ניסוי. 1 × קצר מדי בהרבה ו־4 × ארוך מדי בהרבה.","A model is a rule that predicts":"מודל הוא כלל שחוזה","A model is a rule that guesses what will happen. Predict with it, run real trials, compare, then change the rule until the predictions fit. That is refining a model.":"מודל הוא כלל שמנחש מה יקרה. חוזים איתו, מריצים ניסויים אמיתיים, משווים, ומשנים את הכלל עד שהתחזיות מתאימות. זה נקרא לשפר מודל.","Run the trials. Are the model’s predictions too short or too long?":"הרץ את הניסויים. התחזיות של המודל קצרות מדי או ארוכות מדי?","The rule slider is glowing. Move it one step and run the trials again.":"המחוון של הכלל זוהר. הזז אותו צעד אחד והרץ שוב את הניסויים.","I set the rule to 2 for you. Run the trials and compare.":"קבעתי לך את הכלל על 2. הרץ את הניסויים והשווה.","When the model’s predictions miss the real results, you should…":"כשהתחזיות של המודל מפספסות את התוצאות האמיתיות, כדאי…","Change the rule and test again":"לשנות את הכלל ולבדוק שוב","Keep the rule and ignore the data":"להשאיר את הכלל ולהתעלם מהנתונים","Delete the results":"למחוק את התוצאות","Distance is about 2 × height":"המרחק הוא בערך 2 × גובה","Distance is about 1 × height":"המרחק הוא בערך 1 × גובה","Distance is about 4 × height":"המרחק הוא בערך 4 × גובה","Height":"גובה","Distance = {k} × height":"מרחק = {k} × גובה","Distance":"מרחק","Plant Model":"מודל הצמח","Dot grows bean plants in the lab. Her model: height equals some number of cm for every day.":"דוט מגדלת צמחי שעועית במעבדה. המודל שלה: הגובה הוא מספר כלשהו של ס״מ על כל יום.","Fit the growth rule to the five measured plants, then pin it.":"התאם את כלל הגדילה לחמשת הצמחים שנמדדו, ואז נעץ אותו.","At 3 cm a day the model is within 1 cm of every plant. 5 cm a day predicts far too tall.":"ב־3 ס״מ ביום המודל רחוק עד 1 ס״מ מכל צמח. 5 ס״מ ביום חוזה גבוה מדי בהרבה.","The model starts at 5 cm a day. Compare its guesses with the real heights.":"המודל מתחיל ב־5 ס״מ ביום. השווה את הניחושים שלו לגבהים האמיתיים.","The rule slider is glowing. Too tall means a smaller number.":"המחוון של הכלל זוהר. גבוה מדי אומר מספר קטן יותר.","I set the rule to 3 for you. Run the trials and compare.":"קבעתי לך את הכלל על 3. הרץ את הניסויים והשווה.","Your model predicts too tall every time. Refine it by…":"המודל שלך חוזה גבוה מדי בכל פעם. משפרים אותו על ידי…","Lowering the growth number":"הורדת מספר הגדילה","Raising the growth number":"העלאת מספר הגדילה","Measuring fewer plants":"מדידת פחות צמחים","About 3 cm a day":"בערך 3 ס״מ ביום","About 5 cm a day":"בערך 5 ס״מ ביום","About 1 cm a day":"בערך 1 ס״מ ביום","Days":"ימים","Height = {k} cm × days":"גובה = {k} ס״מ × ימים","Bounce Back":"קפיצה חזרה","Drop a ball and it bounces back part of the way. The model: the bounce is some percent of the drop.":"מפילים כדור והוא קופץ בחזרה חלק מהדרך. המודל: הקפיצה היא אחוז כלשהו מהנפילה.","Find the percent that fits the drops, then pin the rule.":"מצא את האחוז שמתאים לנפילות, ואז נעץ את הכלל.","At 60% every bounce is within 2 cm of the model. 90% and 30% miss by a lot.":"ב־60% כל קפיצה רחוקה עד 2 ס״מ מהמודל. 90% ו־30% מפספסים בהרבה.","Does the ball bounce most of the way back, or less?":"הכדור קופץ בחזרה רוב הדרך, או פחות?","The rule slider is glowing. Try the middle and refine from there.":"המחוון של הכלל זוהר. נסה את האמצע ושפר משם.","I set the rule to 60% for you. Run the trials and compare.":"קבעתי לך את הכלל על 60%. הרץ את הניסויים והשווה.","A model that fits five trials well is…":"מודל שמתאים היטב לחמישה ניסויים הוא…","Good evidence for the rule":"ראיה טובה לכלל","Proof it fits every ball ever":"הוכחה שהוא מתאים לכל כדור אי פעם","Useless":"חסר תועלת","The ball bounces about 60% of the drop":"הכדור קופץ בערך 60% מהנפילה","The ball bounces about 90% of the drop":"הכדור קופץ בערך 90% מהנפילה","The ball bounces about 30% of the drop":"הכדור קופץ בערך 30% מהנפילה","Drop":"נפילה","Bounce = {k}% of the drop":"קפיצה = {k}% מהנפילה","Bounce":"קפיצה","Predict Day 12":"תחזית ליום 12","The bean plants again. Fit the rule, then use the model to predict a day nobody measured.":"שוב צמחי השעועית. התאם את הכלל, ואז השתמש במודל כדי לחזות יום שאף אחד לא מדד.","Fit the growth rule, slide to your prediction for day 12, then pin it.":"התאם את כלל הגדילה, גרור לתחזית שלך ליום 12, ואז נעץ אותה.","The model that fits is 3 cm a day, so day 12 should be about 36 cm.":"המודל שמתאים הוא 3 ס״מ ביום, אז ביום 12 בערך 36 ס״מ.","First make the model fit the five plants.":"קודם תתאים את המודל לחמשת הצמחים.","The rule slider is glowing. When the model fits, 12 days times the rule is your prediction.":"המחוון של הכלל זוהר. כשהמודל מתאים, 12 ימים כפול הכלל זו התחזית שלך.","I set the rule to 3 for you. 3 times 12 is 36: slide to 36.":"קבעתי לך את הכלל על 3. 3 כפול 12 זה 36: גרור ל־36.","A good model lets you…":"מודל טוב מאפשר לך…","Predict cases you did not measure":"לחזות מקרים שלא מדדת","Skip measuring anything":"לדלג על כל מדידה","Change the real results":"לשנות את התוצאות האמיתיות","Day 12":"יום 12","Game Balance":"איזון המשחק","Set the jump power, run 20 test runs, refine, then pin the result.":"קבע את כוח הקפיצה, הרץ 20 הרצות בדיקה, שפר, ואז נעץ את התוצאה.","At jump power 8, 16 of 20 runs finish: about 8 in 10. Power 10 lets everyone finish, which is no fun.":"בכוח קפיצה 8, 16 מתוך 20 הרצות מסתיימות: בערך 8 מתוך 10. בכוח 10 כולם מסיימים, וזה לא כיף.","Run 20 tests. How many finish? Too many means the game is too easy.":"הרץ 20 בדיקות. כמה מסיימים? יותר מדי אומר שהמשחק קל מדי.","The jump slider is glowing. Lower it a step and test again.":"מחוון הקפיצה זוהר. הורד אותו צעד ובדוק שוב.","I set the jump power to 8 for you. Run the tests and count the finishers.":"קבעתי לך את כוח הקפיצה על 8. הרץ את הבדיקות וספור את המסיימים.","Playtest data says 20 of 20 runs finish. The game is…":"נתוני הבדיקה אומרים ש־20 מתוך 20 הרצות מסתיימות. המשחק…","Too easy: refine the jump":"קל מדי: שפר את הקפיצה","Perfectly balanced":"מאוזן בדיוק","Too hard":"קשה מדי","About 8 in 10 runs finish":"בערך 8 מתוך 10 הרצות מסתיימות","Every run finishes":"כל הרצה מסתיימת","Only half the runs finish":"רק חצי מההרצות מסתיימות","Jump power {k}":"כוח קפיצה {k}","Run":"הרצה","Finished":"סיים","Fell":"נפל","One Grade Asked":"שאלו שכבה אחת","I grouped by Grade for you. How many grades are there?":"קיבצתי לך לפי ״שכבה״. כמה שכבות יש?","Grade 3":"כיתה ג׳","Fair: Soccer won clearly":"הוגן: כדורגל ניצח בבירור","Grade":"שכבה","Pick":"בחירה","Tag":"תווית","Who Is Missing?":"מי חסר?","Sorted, the pattern is plain: every No is a veggie eater and every Yes eats meat. The veggie kids were never asked.":"אחרי המיון הדפוס ברור: כל ״לא״ אוכל צמחוני וכל ״כן״ אוכל בשר. את הילדים הצמחונים אף פעם לא שאלו.","Which kids have No in the Voted column? What do they have in common?":"לאילו ילדים יש ״לא״ בעמודה ״הצביע״? מה משותף להם?","The Voted column is glowing. Sort by it.":"העמודה ״הצביע״ זוהרת. מיין לפיה.","I sorted by Voted for you. Read the Lunch column of the No rows.":"מיינתי לך לפי ״הצביע״. קרא את עמודת ״ארוחה״ בשורות של ״לא״.","The veggie eaters never got to vote":"הצמחונים לא קיבלו הזדמנות להצביע","Everyone voted":"כולם הצביעו","The meat eaters were left out":"אוכלי הבשר נשארו בחוץ","Lunch":"ארוחה","Voted":"הצביע","Meat":"בשר","Yes":"כן","Veggie":"צמחוני","No":"לא","Works for Some":"עובד רק לחלק","A voice helper was tested before launch. It was tested mostly on one kind of voice.":"עוזר קולי נבדק לפני ההשקה. הוא נבדק בעיקר על סוג קול אחד.","Who does the voice helper fail?":"אצל מי העוזר הקולי נכשל?","As a share: 90% of deep voices worked but only 50% of high voices. Tested mostly on deep voices, it fails the others.":"בחלקים: 90% מהקולות העמוקים עבדו אבל רק 50% מהקולות הגבוהים. הוא נבדק בעיקר על קולות עמוקים, ולכן נכשל אצל האחרים.","9 worked and 3 worked, but the groups are different sizes. What makes them fair to compare?":"9 עבדו ו־3 עבדו, אבל הקבוצות בגדלים שונים. מה יאפשר להשוות בהוגנות?","Switched to percent for you: 90% against 50%.":"עברתי לאחוזים בשבילך: 90% מול 50%.","To find who a system fails, test it on…":"כדי לגלות אצל מי מערכת נכשלת, בודקים אותה על…","Many different kinds of people":"הרבה סוגים שונים של אנשים","The people who built it":"האנשים שבנו אותה","One kind of voice":"סוג קול אחד","It fails half the high voices":"הוא נכשל אצל חצי מהקולות הגבוהים","It works the same for everyone":"הוא עובד אותו דבר לכולם","It fails the deep voices":"הוא נכשל אצל הקולות העמוקים","Testers":"בודקים","Worked":"עבד","Tested":"נבדקו","Deep voices":"קולות עמוקים","High voices":"קולות גבוהים","Who Else to Ask":"את מי עוד לשאול","Who is in this survey? Who is not?":"מי נמצא בסקר הזה? מי לא?","Group is glowing. Group by Comes by.":"הקיבוץ זוהר. קבץ לפי ״מגיע ב״.","I grouped by Comes by for you: one bar, all Bus. Pick the two groups that are missing.":"קיבצתי לך לפי ״מגיע ב״: עמודה אחת, כולם באוטובוס. בחר את שתי הקבוצות שחסרות.","Just as biased":"מוטה באותה מידה","Fair":"הוגן","Shorter":"קצר יותר","Kids in other grades":"ילדים משכבות אחרות","Kids who walk or bike":"ילדים שהולכים ברגל או רוכבים על אופניים","More Grade 5 bus riders":"עוד נוסעי אוטובוס מכיתה ה׳","The same kids again":"שוב אותם ילדים","Comes by":"מגיע ב","Grade 5":"כיתה ה׳","Our Survey":"הסקר שלנו","Real data comes from real people. Count the answers from your class and chart them.":"נתונים אמיתיים מגיעים מאנשים אמיתיים. ספור את התשובות מהכיתה שלך והכן מהן דיאגרמה.","Enter the tallies with the steppers, make a chart, then pin a claim the chart supports.":"הכנס את הספירות עם הכפתורים, צור דיאגרמה, ואז נעץ טענה שהדיאגרמה תומכת בה.","The chart says: {top} has the most with {a}, {low} the fewest with {b}, {total} answers in all.":"הדיאגרמה אומרת: ל{top} הכי הרבה עם {a}, ל{low} הכי מעט עם {b}, {total} תשובות בסך הכול.","Collect, chart, claim":"לאסוף, לשרטט, לטעון","A survey turns people’s answers into data. Tally each answer, chart the counts, then pin only a claim the chart really shows. Five answers is the least that counts as a case.":"סקר הופך תשובות של אנשים לנתונים. ספור כל תשובה, הכן דיאגרמה של הספירות, ואז נעץ רק טענה שהדיאגרמה באמת מראה. צריך לפחות חמש תשובות כדי שזה ייחשב תיק.","How many kids picked each one? Add them up with the steppers.":"כמה ילדים בחרו בכל אחד? חבר אותם עם הכפתורים.","The Bars button is glowing: a chart shows the shape of your answers.":"כפתור העמודות זוהר: דיאגרמה מראה את הצורה של התשובות שלכם.","I switched to bars for you. Which bar is tallest? Pin that claim.":"עברתי לעמודות בשבילך. איזו עמודה הכי גבוהה? נעץ את הטענה הזאת.","Two kids answered. Is that enough for a claim about the class?":"שני ילדים ענו. זה מספיק לטענה על כל הכיתה?","Not yet: ask more kids":"עוד לא: שאל עוד ילדים","Yes, two is plenty":"כן, שניים זה הרבה","Only if they agree":"רק אם הם מסכימים","Another Class":"כיתה אחרת","A second question for your class. Pro detectives can also load another class and compare shares.":"שאלה שנייה לכיתה שלך. בלשים מקצוענים יכולים גם לטעון כיתה אחרת ולהשוות חלקים.","Tally your class, chart it, and pin a claim. Pro: load the other class and compare by percent.":"ספור את הכיתה שלך, הכן דיאגרמה ונעץ טענה. מקצוען: טען את הכיתה האחרת והשווה לפי אחוזים.","Count each color with the steppers, then make the chart.":"ספור כל צבע עם הכפתורים, ואז צור את הדיאגרמה.","I switched to bars for you. Which bar wins? Pin that claim.":"עברתי לעמודות בשבילך. איזו עמודה מנצחת? נעץ את הטענה הזאת.","Two classes of different sizes are compared fairly by…":"משווים בהוגנות שתי כיתות בגדלים שונים לפי…","Percent of each class":"אחוז מכל כיתה","Raw counts":"מספרים גולמיים","Who shouted loudest":"מי צעק הכי חזק","Open Tally":"ספירה חופשית","Your own survey. Pick a question, tally the class, chart it, claim it. Make as many charts as you like.":"הסקר שלך. בחר שאלה, ספור את הכיתה, הכן דיאגרמה, טען טענה. צור כמה דיאגרמות שתרצה.","Pick a question first, then count the answers.":"קודם בחר שאלה, ואז ספור את התשובות.","The Bars button is glowing once you have five answers or more.":"כפתור העמודות זוהר כשיש חמש תשובות או יותר.","I switched to bars for you. Pin the claim about the tallest bar.":"עברתי לעמודות בשבילך. נעץ את הטענה על העמודה הכי גבוהה.","Crowdsource the class data":"לאסוף נתונים מכל הכיתה","Hide the results":"להסתיר את התוצאות","Pick a winner":"לבחור מנצח","This is a Pro chapter. Try it?":"זה פרק למקצוענים. לנסות?","Not now":"לא עכשיו","Try it":"לנסות","“{claim}”":"״{claim}״","It is a tie. Count a few more answers, or pin the tie.":"יש תיקו. ספור עוד כמה תשובות, או נעץ את התיקו.","{a} and {b} are tied for the most.":"{a} ו{b} בתיקו על המקום הראשון.","A table holds facts in rows and columns. Sorting puts the rows in order, and grouping counts how many of each kind. Tap a column name to sort by it. The right view makes the answer pop out.":"בטבלה יש עובדות בשורות ובעמודות. מיון מסדר את השורות, וקיבוץ סופר כמה יש מכל סוג. הקש על שם עמודה כדי למיין לפיה. התצוגה הנכונה גורמת לתשובה לקפוץ לעין.","Sorted by Seconds from small to big, the fastest runner is in the…":"במיון לפי ״שניות״ מהקטן לגדול, הרץ הכי מהיר נמצא ב…","Top row":"שורה עליונה","Bottom row":"שורה תחתונה","Middle row":"שורה אמצעית","Two days of data: 3 cm, then 5 cm. “It will be 20 cm by day 10” is…":"נתונים של יומיים: 3 ס״מ, ואז 5 ס״מ. ״ביום 10 הוא יהיה 20 ס״מ״ היא…","Sorted by shoe size, the Books numbers go up and down: 4, 3, 6, 1, 2, 5. No pattern, so not supported.":"במיון לפי מידת נעליים, המספרים ב״ספרים״ עולים ויורדים: 4, 3, 6, 1, 2, 5. אין דפוס, אז לא נתמכת.","Does the Books column go up when Shoe size goes up? Sort to find out.":"האם ״ספרים״ עולה כשמידת הנעליים עולה? מיין כדי לגלות.","Shoe size is glowing. Sort by it, then read the whole Books column.":"״מידת נעליים״ זוהרת. מיין לפיה, ואז קרא את כל עמודת ״ספרים״.","Sorted by Shoe size for you: 4, 3, 6, 1, 2, 5. No pattern: not supported.":"מיינתי לך לפי מידת נעליים: 4, 3, 6, 1, 2, 5. אין דפוס: לא נתמכת.","Laps: 4, 6, 2, 5. “Everyone ran at least 3 laps” is…":"הקפות: 4, 6, 2, 5. ״כולם רצו לפחות 3 הקפות״ היא…","Not supported: one ran 2":"לא נתמכת: אחד רץ 2","The sign-up sheet was passed around twice. Some kids are on it two times.":"דף ההרשמה עבר בין הילדים פעמיים. חלק מהילדים רשומים בו פעמיים.","Your team’s runner game is too easy: every playtester reaches the end. Tune the jump so about 8 in 10 test runs finish.":"משחק הריצה של הצוות שלך קל מדי: כל בודק מגיע לסוף. כוונן את הקפיצה כך שבערך 8 מתוך 10 הרצות בדיקה יסתיימו.","A new recess app was tested only by Grade 3 before launch. Its poster says the whole school loves the soccer button. Here are the test results.":"אפליקציה חדשה להפסקה נבדקה לפני ההשקה רק על ידי כיתה ג׳. בפוסטר כתוב שכל בית הספר אוהב את כפתור הכדורגל. הנה תוצאות הבדיקה.","Was this app tested fairly for the whole school?":"האם האפליקציה נבדקה בהוגנות בשביל כל בית הספר?","Grouped by Grade there is one bar: every tester was in Grade 3. The other grades never tried the app.":"בקיבוץ לפי ״שכבה״ יש עמודה אחת: כל הבודקים היו מכיתה ג׳. השכבות האחרות אף פעם לא ניסו את האפליקציה.","Test technology on everyone":"בודקים טכנולוגיה על כולם","Apps, games and gadgets are designed from test data. If only one group tests them, they may not work for everyone. Good design is tested by many kinds of people, including people who see, hear or move differently. That is called accessibility.":"אפליקציות, משחקים ומכשירים מתוכננים לפי נתוני בדיקה. אם רק קבוצה אחת בודקת אותם, ייתכן שהם לא יעבדו לכולם. עיצוב טוב נבדק על ידי הרבה סוגים של אנשים, כולל אנשים שרואים, שומעים או זזים אחרת. זה נקרא נגישות.","Who tested this app? Which column tells you?":"מי בדק את האפליקציה הזאת? איזו עמודה אומרת לך?","Group is glowing. Group by Grade to see who tested it.":"הקיבוץ זוהר. קבץ לפי ״שכבה״ כדי לראות מי בדק אותה.","An app that only Grade 3 tested may not work well for…":"אפליקציה שרק כיתה ג׳ בדקה אולי לא תעבוד טוב בשביל…","Nobody at all":"אף אחד בכלל","Not fair: only Grade 3 tested it":"לא הוגן: רק כיתה ג׳ בדקה אותה","Fair: eight kids tested it":"הוגן: שמונה ילדים בדקו אותה","Burgers won the vote on the new lunch-order screen. But the screen was set up in the meat line, and some kids never got to use it.":"המבורגרים ניצחו בהצבעה במסך ההזמנות החדש של ארוחת הצהריים. אבל המסך הוצב בתור של הבשר, וחלק מהילדים אף פעם לא השתמשו בו.","Who was left out of the vote on the screen?":"מי נשאר בחוץ בהצבעה במסך?","A game’s red and green clues look the same to some players. The design…":"רמזים אדומים וירוקים במשחק נראים אותו דבר לחלק מהשחקנים. העיצוב…","Leaves some players out: add shapes too":"משאיר שחקנים בחוץ: תוסיף גם צורות","Is fine for most players":"בסדר לרוב השחקנים","Is more fun":"יותר כיפי","The council built a new bike-shed sign-up screen. Every tester came from the Grade 5 bus stop.":"מועצת התלמידים בנתה מסך הרשמה חדש לחניון האופניים. כל הבודקים הגיעו מתחנת האוטובוס של כיתה ה׳.","Pick the two groups who should test the sign-up screen next.":"בחר את שתי הקבוצות שצריכות לבדוק את מסך ההרשמה עכשיו.","Every tester is in Grade 5 and comes by bus. The missing testers are other grades and kids who walk or bike, the very kids who will use the bike shed.":"כל בודק הוא מכיתה ה׳ ומגיע באוטובוס. הבודקים החסרים הם משכבות אחרות וילדים שהולכים ברגל או רוכבים, בדיוק הילדים שישתמשו בחניון האופניים.","More testers from the same group make a test of new technology…":"עוד בודקים מאותה קבוצה הופכים בדיקה של טכנולוגיה חדשה ל…","Pick a question, enter the tallies, make a chart and pin a claim. On the projector, add each chart to the class pool.":"בחר שאלה, הכנס את הספירות, צור דיאגרמה ונעץ טענה. במקרן, הוסף כל דיאגרמה למאגר הכיתה.","Every pair reads its tallies out and the teacher pools them on the projector. That is a way to…":"כל זוג מקריא את הספירות שלו והמורה מאגד אותן במקרן. זו דרך…","The chart says: it is a tie at the top with {a} each, {low} the fewest with {b}, {total} answers in all.":"הדיאגרמה אומרת: תיקו במקום הראשון עם {a} לכל אחד, ל{low} הכי מעט עם {b}, {total} תשובות בסך הכול.","Kind":"סוג"}} });
